    ('fab3ca92-b4d6-53e0-b06b-eb3174505645'::uuid, 'Nombres et calculs'),
    ('7aaec3ed-c892-51f4-9408-c6383039372a'::uuid, 'Nombres et calculs'),
    ('b5b4c57e-81a5-5e7e-b94c-1da2647e723d'::uuid, 'Nombres et calculs'),
    ('7a85fcba-5f8b-5eb6-aabf-5bcc73b851ca'::uuid, 'Nombres et calculs'),
    ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 'Nombres et calculs'),
    ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 'Nombres et calculs'),
    ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 'Géométrie'),
    ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 'Géométrie'),
    ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 'Géométrie'),
    ('e2803fe6-baa3-5cc6-b2e1-54da7febc1cd'::uuid, 'Géométrie'),
    ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 'Fonctions'),
    ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 'Fonctions'),
    ('acc9b508-36d7-59bf-a1d2-79ea5d1bbdc3'::uuid, 'Fonctions'),
    ('0336f88f-89aa-50c3-b8f0-9a437b1138d7'::uuid, 'Fonctions'),
    ('68f4b5d4-7e86-5ae9-b5b2-8243fed0fb0b'::uuid, 'Fonctions'),
    ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 'Fonctions'),
    ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 'Statistiques et probabilités'),
    ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 'Statistiques et probabilités'),
    ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 'Statistiques et probabilités'),
