    ('19597458-2648-50af-b44b-abe265c1dedc'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Comment s’appelle la courbe de la fonction inverse ?', 'mcq', '["Une hyperbole","Une parabole","Une droite","Une sinusoïde"]'::jsonb, 0, 'Elle est formée de deux branches.', 3),
